def run_spec(tool, args):
    """The `run` entry of a manifest case: registry id and parameters (None and empty are left out)."""
    if tool not in RUN:
        return None
    rid, names = RUN[tool]
    return {"tool": rid, "params": {n: a for n, a in zip(names, args) if n and a not in (None, "")}}


